def gen(rng):
    def fmt(ws):
        return str(len(ws)) + "\n" + " ".join(ws)
    def rw(lo, hi, alpha):
        return "".join(rng.choice(alpha) for _ in range(rng.randint(lo, hi)))
    tests = [fmt(["a"]), fmt(["b", "a"]), fmt(["z", "z", "z"]), fmt(["abc", "ab", "a"]), fmt(["ba", "ab", "aa", "bb"]),
             fmt("the quick brown fox jumps over the lazy dog".split()), fmt(["apple", "fig", "pear", "date", "kiwi"])]
    for _ in range(30):
        n = rng.randint(1, 10)
        tests.append(fmt([rw(1, 4, "abc") for _ in range(n)]))
    for _ in range(10):
        n = rng.randint(10, 30)
        tests.append(fmt([rw(1, 6, "abcdef") for _ in range(n)]))
    N = 100000
    tests.append(fmt([rw(1, 15, "abcdefghijklmnopqrstuvwxyz") for _ in range(N)]))
    tests.append(fmt([rw(15, 15, "ab") for _ in range(N)]))
    tests.append(fmt([rw(1, 3, "ab") for _ in range(N)]))
    tests.append(fmt(["zzzzzzzzzzzzzzz"] * N))
    return tests
